import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    scope {
        let slow = task effect io { io.println("slow") }
        let fast = task effect io { io.println("fast") }
        let v = select {
            case r1 = slow.await() => 1
            case r2 = fast.await() => 2
        }
        if v == 1 {
            io.println("first")
        } else {
            io.println("second")
        }
    }
    return Ok(())
}
